<template><div class="app-container p-4"><h2>资源审核</h2><p>仅查看资源所有者主动提交的版本。通过后向企业员工开放查看与使用，依赖权限仍单独校验。</p><el-alert v-if="error" :title="error" type="error" :closable="false"/><el-table v-loading="loading" :data="rows"><el-table-column prop="name" label="资源名称"/><el-table-column prop="resource_type" label="类型"/><el-table-column prop="version" label="提交版本"/><el-table-column label="审核状态"><template #default="{row}">{{({PENDING:"待审核",APPROVED:"已通过",REJECTED:"未通过/已撤回"} as Record<string,string>)[row.state]}}</template></el-table-column><el-table-column label="操作"><template #default="{row}"><el-button @click="open(row.id)">查看提交内容</el-button></template></el-table-column></el-table><div class="mt-4"><el-button :disabled="page===1||loading" @click="page--;load()">上一页</el-button><span>第 {{page}} 页</span><el-button :disabled="rows.length<30||loading" @click="page++;load()">下一页</el-button></div>
 <el-dialog v-model="visible" title="审核提交版本" width="850px"><el-alert v-if="error" :title="error" type="error" :closable="false"/><template v-if="detail"><h3>{{detail.metadata.name}} · V{{detail.version}}</h3><p>{{detail.metadata.description}}</p><el-descriptions :column="1" border><el-descriptions-item v-for="(value,key) in detail.config" :key="key" :label="labels[key]||String(key)"><pre class="value">{{typeof value==='object'?JSON.stringify(value,null,2):value}}</pre></el-descriptions-item></el-descriptions><h4 v-if="detail.documents.length">本次提交的知识文档</h4><el-button v-for="doc in detail.documents" :key="doc.document_id" @click="previewDoc(doc.document_id)">{{doc.filename}} · V{{doc.version}}</el-button><pre v-if="source" class="source">{{source}}</pre><el-alert title="MCP 连接凭据不在模板内。通过资源审核不会授予依赖模型、知识或个人连接的权限。" type="info" :closable="false"/><el-input v-if="detail.state==='PENDING'" v-model="reason" type="textarea" aria-label="审核意见" placeholder="填写明确的审核意见" maxlength="1000"/><div class="mt-4" v-if="detail.state==='PENDING'"><el-button :disabled="busy||!reason.trim()" @click="decide(false)">驳回</el-button><el-button type="primary" :disabled="busy||!reason.trim()" @click="decide(true)">通过并发布</el-button></div></template></el-dialog></div></template>
<script setup lang="ts">
import request from '@/utils/request';
const rows=ref<any[]>([]),page=ref(1),loading=ref(true),error=ref(''),visible=ref(false),detail=ref<any>(),reason=ref(''),source=ref(''),busy=ref(false);
const labels:Record<string,string>={instruction:'指令',modelId:'模型 ID',skillIds:'技能依赖',mcpIds:'MCP 依赖',toolIds:'工具依赖',knowledgeIds:'知识依赖',source:'技能原文',manifest:'技能元数据',format:'格式',transport:'传输协议',authType:'认证类型',allowedTools:'允许工具',endpoint:'服务地址',managedProfile:'托管服务',timeoutSeconds:'超时秒数',toolType:'工具类型',precision:'小数精度',avatar:'头像符号'};
async function load(){loading.value=true;try{rows.value=(await request({url:'/ai/admin/reviews',method:'get',params:{page:page.value}})).data;}catch{error.value='审核列表加载失败，请刷新重试。';}finally{loading.value=false;}}
async function open(id:string){error.value='';try{detail.value=(await request({url:'/ai/admin/reviews/'+id,method:'get'})).data;reason.value='';source.value='';visible.value=true;}catch{error.value='无法查看此审核记录。';}}
async function previewDoc(id:string){try{const r=await request({url:'/ai/admin/reviews/'+detail.value.id+'/documents/'+id,method:'get'});source.value=r.data.filename+' · V'+r.data.version+'\n'+r.data.content;}catch{error.value='文档读取失败。';}}
async function decide(approve:boolean){busy.value=true;try{await request({url:'/ai/admin/reviews/'+detail.value.id+'/decision',method:'post',data:{approve,reason:reason.value}});visible.value=false;await load();ElMessage.success(approve?'版本已通过并公开':'已驳回申请');}catch{error.value='审核未完成：版本可能已变更、申请已撤回或当前账号不能自审私人资源。';}finally{busy.value=false;}}
onMounted(load);
</script>
<style scoped>.value{white-space:pre-wrap;overflow-wrap:anywhere;max-height:300px;overflow:auto}.source{white-space:pre-wrap;max-height:360px;overflow:auto;padding:16px;background:#f5f7fa}</style>
